// ── Step Builder Row ─────────────────────────────────────────

function StepRow({ step, onEdit, onDelete, onGenerateAI }) {
  const ChannelIcon = CHANNEL_ICONS[step.channel] || Mail;
  const channelColor = CHANNEL_COLORS[step.channel] || CHANNEL_COLORS.email;
  const [expanded, setExpanded] = useState(false);

  return (
    <div className="bg-white rounded-lg border border-gray-100 p-4 hover:shadow-sm transition-shadow">
      <div className="flex items-center gap-3">
        {/* Step number */}
        <div className="w-8 h-8 rounded-full bg-gradient-to-br from-blue-500 to-cyan-500 flex items-center justify-center text-white text-xs font-bold shrink-0">
          {step.step_number}
        </div>
        {/* Channel */}
        <div className={`w-8 h-8 rounded-lg flex items-center justify-center ${channelColor} shrink-0`}>
          <ChannelIcon size={14} />
        </div>
        {/* Info */}
        <div className="flex-1 min-w-0">
          <div className="flex items-center gap-2">
            <span className="text-sm font-medium text-gray-900 capitalize">{step.channel}</span>
            {step.ai_generated && (
              <span className="text-[10px] bg-orange-50 text-orange-600 px-1.5 py-0.5 rounded-full font-medium flex items-center gap-0.5">
                <Sparkles size={8} /> AI
              </span>
            )}
          </div>
          <span className="text-xs text-gray-400">
            {step.delay_days === 0 ? 'Same day' : `Wait ${step.delay_days} day${step.delay_days > 1 ? 's' : ''}`}
            {step.send_if !== 'always' && ` • Only if ${step.send_if.replace(/_/g, ' ')}`}
          </span>
        </div>
        {/* Actions */}
        <div className="flex items-center gap-1">
          <button onClick={() => onGenerateAI(step)} className="p-1.5 text-orange-400 hover:text-orange-600 hover:bg-orange-50 rounded transition-colors" title="Generate with AI">
            <Sparkles size={14} />
          </button>
          <button onClick={() => onEdit(step)} className="p-1.5 text-gray-400 hover:text-gray-600 hover:bg-gray-50 rounded transition-colors">
            <Edit3 size={14} />
          </button>
          <button onClick={() => onDelete(step.id)} className="p-1.5 text-gray-400 hover:text-red-500 hover:bg-red-50 rounded transition-colors">
            <Trash2 size={14} />
          </button>
          <button onClick={() => setExpanded(!expanded)} className="p-1.5 text-gray-400 hover:text-gray-600 hover:bg-gray-50 rounded transition-colors">
            {expanded ? <ChevronUp size={14} /> : <ChevronDown size={14} />}
          </button>
        </div>
      </div>
      {expanded && (
        <div className="mt-3 pl-11 space-y-2">
          {step.subject && (
            <div>
              <span className="text-[10px] text-gray-400 uppercase font-medium">Subject</span>
              <p className="text-xs text-gray-700">{step.subject}</p>
            </div>
          )}
          {step.body && (
            <div>
              <span className="text-[10px] text-gray-400 uppercase font-medium">Message</span>
              <div className="bg-gray-50 rounded-lg p-3 mt-0.5">
                <p className="text-xs text-gray-700 whitespace-pre-wrap">{step.body}</p>
              </div>
            </div>
          )}
          <div className="flex items-center gap-4 text-[10px] text-gray-400">
            <span>Tone: <strong className="text-gray-600 capitalize">{step.tone}</strong></span>
            <span>Skip if replied: <strong className="text-gray-600">{step.skip_if_replied ? 'Yes' : 'No'}</strong></span>
          </div>
        </div>
      )}
    </div>
  );
}

// ── Sequence Card ────────────────────────────────────────────

function SequenceCard({ sequence, onSelect, onToggleStatus, onDelete }) {
  const status = STATUS_STYLES[sequence.status] || STATUS_STYLES.draft;
  const replyRate = sequence.total_enrolled > 0
    ? Math.round((sequence.total_replied / sequence.total_enrolled) * 100)
    : 0;

  return (
    <div
      className="bg-white rounded-xl border border-gray-100 p-5 hover:shadow-md transition-all cursor-pointer group"
      onClick={() => onSelect(sequence.id)}
    >
      <div className="flex items-start justify-between mb-3">
        <div className="flex-1 min-w-0">
          <h3 className="text-sm font-semibold text-gray-900 truncate group-hover:text-blue-600 transition-colors">{sequence.name}</h3>
          {sequence.description && <p className="text-xs text-gray-500 mt-0.5 line-clamp-1">{sequence.description}</p>}
        </div>
        <span className={`px-2 py-0.5 rounded-full text-[10px] font-medium ${status.bg} ${status.text} shrink-0 ml-2`}>{status.label}</span>
      </div>

      <div className="grid grid-cols-4 gap-3 mb-3">
        <div>
          <span className="text-[10px] text-gray-400 block">Steps</span>
          <span className="text-sm font-semibold text-gray-900">{sequence.total_steps}</span>
        </div>
        <div>
          <span className="text-[10px] text-gray-400 block">Enrolled</span>
          <span className="text-sm font-semibold text-gray-900">{sequence.total_enrolled}</span>
        </div>
        <div>
          <span className="text-[10px] text-gray-400 block">Replied</span>
          <span className="text-sm font-semibold text-gray-900">{sequence.total_replied}</span>
        </div>
        <div>
          <span className="text-[10px] text-gray-400 block">Reply %</span>
          <span className="text-sm font-semibold text-gray-900">{replyRate}%</span>
        </div>
      </div>

      <div className="flex items-center gap-2 pt-2 border-t border-gray-50" onClick={(e) => e.stopPropagation()}>
        <span className="text-xs text-gray-400 capitalize flex items-center gap-1">
          {React.createElement(CHANNEL_ICONS[sequence.default_channel] || Mail, { size: 10 })}
          {sequence.default_channel}
        </span>
        <div className="flex-1" />
        {sequence.status !== 'archived' && (
          <button
            onClick={() => onToggleStatus(sequence.id, sequence.status === 'active' ? 'paused' : 'active')}
            className={`text-xs px-2.5 py-1 rounded-lg font-medium transition-colors ${
              sequence.status === 'active'
                ? 'bg-amber-50 text-amber-600 hover:bg-amber-100'
                : 'bg-emerald-50 text-emerald-600 hover:bg-emerald-100'
            }`}
          >
            {sequence.status === 'active' ? 'Pause' : 'Activate'}
          </button>
        )}
        <button onClick={() => onDelete(sequence.id)} className="text-xs px-2 py-1 text-red-400 hover:text-red-600 hover:bg-red-50 rounded-lg transition-colors">
          <Trash2 size={12} />
        </button>
      </div>
    </div>
  );
}

// ── New Sequence Modal ───────────────────────────────────────

function NewSequenceModal({ isOpen, onClose, onCreate }) {
  const [name, setName] = useState('');
  const [description, setDescription] = useState('');
  const [channel, setChannel] = useState('email');
  const [saving, setSaving] = useState(false);
  const [error, setError] = useState('');

  if (!isOpen) return null;

  const handleSubmit = async (e) => {
    e.preventDefault();
    if (!name.trim()) return;
    setSaving(true);
    setError('');
    try {
      await onCreate({ name: name.trim(), description: description.trim(), default_channel: channel });
      setName('');
      setDescription('');
      setChannel('email');
      setError('');
      onClose();
    } catch (err) {
      setError(err.message || 'Failed to create sequence');
    } finally {
      setSaving(false);
    }
  };

  return (
    <div className="fixed inset-0 flex items-center justify-center bg-black bg-opacity-50 z-50">
      <div className="bg-white rounded-lg shadow-xl p-6 w-full max-w-md relative">
        <button onClick={onClose} className="absolute top-4 right-4 text-gray-400 hover:text-gray-600">
          <X size={20} />
        </button>

        <h2 className="text-xl font-bold text-gray-900 mb-5">New Sequence</h2>

        {error && (
          <div className="mb-4 p-3 bg-red-50 border border-red-200 rounded-md text-sm text-red-700">{error}</div>
        )}

        <form onSubmit={handleSubmit} className="space-y-4">
          <div>
            <label className="block text-sm font-medium text-gray-700 mb-1">Sequence Name *</label>
            <input
              value={name}
              onChange={(e) => setName(e.target.value)}
              className="w-full px-3 py-2 border border-gray-300 rounded-md text-sm focus:ring-2 focus:ring-blue-500 focus:border-transparent"
              placeholder="e.g. Cold Outreach - VP Sales"
              required
            />
          </div>
          <div>
            <label className="block text-sm font-medium text-gray-700 mb-1">Description</label>
            <textarea
              value={description}
              onChange={(e) => setDescription(e.target.value)}
              rows={2}
              className="w-full px-3 py-2 border border-gray-300 rounded-md text-sm focus:ring-2 focus:ring-blue-500 focus:border-transparent resize-none"
              placeholder="Describe the purpose of this sequence..."
            />
          </div>
          <div>
            <label className="block text-sm font-medium text-gray-700 mb-1">Primary Channel</label>
            <div className="flex gap-2">
              {(['email', 'linkedin', 'call', 'task']).map((ch) => {
                const Icon = CHANNEL_ICONS[ch];
                return (
                  <button
                    key={ch}
                    type="button"
                    onClick={() => setChannel(ch)}
                    className={`flex items-center gap-1.5 px-3 py-2 rounded-md text-xs font-medium transition-all ${
                      channel === ch ? 'bg-blue-50 text-blue-600 ring-1 ring-blue-200' : 'bg-gray-50 text-gray-600 hover:bg-gray-100'
                    }`}
                  >
                    <Icon size={12} /> <span className="capitalize">{ch}</span>
                  </button>
                );
              })}
            </div>
          </div>
          <div className="flex justify-end gap-3 pt-2">
            <button
              type="button"
              onClick={onClose}
              className="px-4 py-2 text-sm font-medium text-gray-700 bg-gray-100 rounded-md hover:bg-gray-200 transition-colors"
            >
              Cancel
            </button>
            <button
              type="submit"
              disabled={!name.trim() || saving}
              className="px-4 py-2 text-sm font-medium text-white bg-blue-600 rounded-md hover:bg-blue-700 disabled:opacity-50 disabled:cursor-not-allowed transition-colors"
            >
              {saving ? 'Creating...' : 'Create Sequence'}
            </button>
          </div>
        </form>
      </div>
    </div>
  );
}

// ── Enrollment List ──────────────────────────────────────────

function EnrollmentList({ enrollments, onUpdateStatus }) {
  if (enrollments.length === 0) {
    return (
      <div className="text-center py-8 text-gray-400">
        <Users size={24} className="mx-auto mb-2 opacity-50" />
        <p className="text-xs">No prospects enrolled yet</p>
      </div>
    );
  }

  return (
    <div className="space-y-2">
      {enrollments.map((e) => {
        const st = ENROLLMENT_STATUS[e.status] || ENROLLMENT_STATUS.active;
        return (
          <div key={e.id} className="flex items-center gap-3 px-3 py-2.5 bg-gray-50 rounded-lg">
            <div className="w-8 h-8 bg-gradient-to-br from-purple-500 to-pink-500 rounded-full flex items-center justify-center text-white text-xs font-bold shrink-0">
              {(e.prospect_name || '?')[0].toUpperCase()}
            </div>
            <div className="flex-1 min-w-0">
              <span className="text-xs font-medium text-gray-900 block truncate">{e.prospect_name || 'Unknown'}</span>
              <span className="text-[10px] text-gray-400">Step {e.current_step} • {e.prospect_company || e.prospect_email || ''}</span>
            </div>
            <span className={`px-2 py-0.5 rounded-full text-[10px] font-medium ${st.bg} ${st.text}`}>{st.label}</span>
          </div>
        );
      })}
    </div>
  );
}

// ── Template Card ────────────────────────────────────────────

function TemplateCard({ template, onUse, loading }) {
  const channels = [...new Set(template.steps.map(s => s.channel))];
  return (
    <div className="bg-white rounded-xl border border-gray-100 p-4 hover:shadow-md transition-all group">
      <div className={`w-9 h-9 bg-gradient-to-br ${template.color} rounded-lg flex items-center justify-center mb-3 shadow-sm`}>
        <template.icon size={16} className="text-white" />
      </div>
      <h4 className="text-xs font-semibold text-gray-900 mb-0.5">{template.name}</h4>
      <p className="text-[10px] text-gray-500 mb-3 line-clamp-2">{template.description}</p>
      <div className="flex items-center gap-2 mb-3">
        <span className="text-[10px] text-gray-400">{template.steps.length} steps</span>
        <span className="text-[10px] text-gray-300">•</span>
        <div className="flex gap-1">
          {channels.map(ch => {
            const Icon = CHANNEL_ICONS[ch];
            return <Icon key={ch} size={10} className="text-gray-400" />;
          })}
        </div>
      </div>
      <button
        onClick={onUse}
        disabled={loading}
        className="w-full text-[11px] font-medium px-3 py-1.5 bg-gray-50 text-gray-600 rounded-lg hover:bg-blue-50 hover:text-blue-600 transition-colors disabled:opacity-50"
      >
        {loading ? 'Creating...' : 'Use Template'}
      </button>
    </div>
  );
}

// ── Main Component ───────────────────────────────────────────

export default function SequencesCadences({ organizationId, userId }) {
  const {
    sequences, summary, activeSequence, enrollments, loading, error,
    fetchSequences, fetchSequenceDetail, createSequence, updateSequence,
    deleteSequence, upsertStep, deleteStep, generateStepContent,
  } = useSequences(organizationId, userId);

  const [view, setView] = useState('list'); // 'list' | 'detail'
  const [showNewModal, setShowNewModal] = useState(false);
  const [generatingStep, setGeneratingStep] = useState(null);
  const [creatingFromTemplate, setCreatingFromTemplate] = useState(null);

  const handleSelectSequence = (id) => {
    fetchSequenceDetail(id);
    setView('detail');
  };

  const handleBack = () => {
    setView('list');
    fetchSequences();
  };

  const handleAddStep = async () => {
    if (!activeSequence) return;
    const stepNumber = (activeSequence.steps?.length || 0) + 1;
    await upsertStep({
      sequence_id: activeSequence.id,
      step_number: stepNumber,
      channel: activeSequence.default_channel || 'email',
      delay_days: stepNumber === 1 ? 0 : 2,
      tone: 'professional',
      send_if: 'no_reply',
      skip_if_replied: true,
    });
  };

  const handleGenerateStepAI = async (step) => {
    setGeneratingStep(step.id);
    try {
      const result = await generateStepContent(step.sequence_id, step.step_number, {
        channel: step.channel,
        tone: step.tone || 'professional',
      });
      if (result?.subject || result?.body) {
        await upsertStep({
          ...step,
          subject: result.subject || step.subject,
          body: result.body || step.body,
          ai_generated: true,
        });
      }
    } catch {
      // Silently handle — the hook shows the error
    }
    setGeneratingStep(null);
  };

  const handleCreateFromTemplate = async (template) => {
    setCreatingFromTemplate(template.id);
    try {
      const seq = await createSequence({
        name: template.name,
        description: template.description,
        default_channel: template.default_channel,
      });
      for (const step of template.steps) {
        await upsertStep({
          sequence_id: seq.id,
          step_number: step.step_number,
          channel: step.channel,
          delay_days: step.delay_days,
          subject: step.subject || null,
          tone: step.tone || 'professional',
          send_if: step.send_if || 'no_reply',
          skip_if_replied: step.skip_if_replied ?? true,
          ai_generated: false,
          metadata: {},
        });
      }
      await fetchSequenceDetail(seq.id);
      setView('detail');
    } catch (err) {
      // Error state handled by hook
    }
    setCreatingFromTemplate(null);
  };

  if (loading && sequences.length === 0) {
    return (
      <div className="flex items-center justify-center py-16">
        <RefreshCw size={20} className="animate-spin text-blue-500 mr-2" />
        <span className="text-sm text-gray-500">Loading sequences...</span>
      </div>
    );
  }

  // ── Detail View ──────────────────────────────────

  if (view === 'detail' && activeSequence) {
    const steps = activeSequence.steps || [];
    const status = STATUS_STYLES[activeSequence.status] || STATUS_STYLES.draft;

    return (
      <div className="space-y-4">
        {/* Back & Header */}
        <div className="flex items-center gap-3">
          <button onClick={handleBack} className="text-xs text-gray-500 hover:text-gray-700 flex items-center gap-1">
            <ChevronRight size={12} className="rotate-180" /> Back
          </button>
          <div className="flex-1">
            <div className="flex items-center gap-2">
              <h2 className="text-lg font-bold text-gray-900">{activeSequence.name}</h2>
              <span className={`px-2 py-0.5 rounded-full text-[10px] font-medium ${status.bg} ${status.text}`}>{status.label}</span>
            </div>
            {activeSequence.description && <p className="text-xs text-gray-500">{activeSequence.description}</p>}
          </div>
          <div className="flex items-center gap-2">
            {activeSequence.status !== 'archived' && (
              <button
                onClick={() => updateSequence(activeSequence.id, { status: activeSequence.status === 'active' ? 'paused' : 'active' })}
                className={`text-xs px-3 py-1.5 rounded-lg font-medium transition-colors ${
                  activeSequence.status === 'active'
                    ? 'bg-amber-50 text-amber-600 hover:bg-amber-100'
                    : 'bg-emerald-50 text-emerald-600 hover:bg-emerald-100'
                }`}
              >
                {activeSequence.status === 'active' ? 'Pause' : 'Activate'}
              </button>
            )}
          </div>
        </div>

        <div className="grid grid-cols-1 lg:grid-cols-3 gap-4">
          {/* Steps */}
          <div className="lg:col-span-2 space-y-3">
            <div className="flex items-center justify-between">
              <h3 className="text-sm font-semibold text-gray-900">Steps ({steps.length})</h3>
              <button onClick={handleAddStep} className="flex items-center gap-1.5 px-3 py-1.5 bg-blue-50 text-blue-600 text-xs font-medium rounded-lg hover:bg-blue-100 transition-colors">
                <Plus size={12} /> Add Step
              </button>
            </div>
            {steps.length === 0 ? (
              <div className="bg-gray-50 rounded-xl p-8 text-center">
                <ClipboardList size={24} className="mx-auto mb-2 text-gray-300" />
                <p className="text-xs text-gray-400 mb-3">No steps yet. Add your first step to get started.</p>
                <button onClick={handleAddStep} className="px-4 py-2 bg-blue-600 text-white text-xs font-medium rounded-lg hover:bg-blue-700">
                  Add First Step
                </button>
              </div>
            ) : (
              <div className="space-y-2">
                {steps.map((step, i) => (
                  <React.Fragment key={step.id}>
                    <StepRow
                      step={step}
                      onEdit={(s) => { /* Edit would open a modal — keeping scope focused */ }}
                      onDelete={(id) => deleteStep(id, activeSequence.id)}
                      onGenerateAI={handleGenerateStepAI}
                    />
                    {i < steps.length - 1 && (
                      <div className="flex items-center justify-center py-1">
                        <div className="w-0.5 h-4 bg-gray-200" />
                      </div>
                    )}
                  </React.Fragment>
                ))}
              </div>
            )}
          </div>

          {/* Enrollments sidebar */}
          <div className="space-y-3">
            <h3 className="text-sm font-semibold text-gray-900">Enrollments ({enrollments.length})</h3>
            <div className="bg-white rounded-xl border border-gray-100 p-4">
              <EnrollmentList enrollments={enrollments} onUpdateStatus={() => {}} />
            </div>
          </div>
        </div>
      </div>
    );
  }

  // ── List View ────────────────────────────────────

  return (
    <div className="space-y-4">
      <SummaryCards summary={summary} />

      {error && (
        <div className="bg-red-50 border border-red-200 rounded-xl p-3 text-xs text-red-600 flex items-center gap-2">
          <XCircle size={14} /> {error}
        </div>
      )}

      {/* Sequence Templates */}
      <div>
        <h3 className="text-sm font-semibold text-gray-900 mb-2">Sequence Templates</h3>
        <div className="grid grid-cols-2 md:grid-cols-3 lg:grid-cols-5 gap-3">
          {SEQUENCE_TEMPLATES.map((tmpl) => (
            <TemplateCard
              key={tmpl.id}
              template={tmpl}
              onUse={() => handleCreateFromTemplate(tmpl)}
              loading={creatingFromTemplate === tmpl.id}
            />
          ))}
        </div>
      </div>

      {/* Header */}
      <div className="flex items-center justify-between">
        <h3 className="text-sm font-semibold text-gray-900">Sequences</h3>
        <button
          onClick={() => setShowNewModal(true)}
          className="flex items-center gap-1.5 px-4 py-2 bg-gradient-to-r from-blue-500 to-cyan-500 text-white text-xs font-medium rounded-lg hover:shadow-md transition-all"
        >
          <Plus size={14} /> New Sequence
        </button>
      </div>

      {/* Grid */}
      {sequences.length === 0 ? (
        <div className="bg-white rounded-2xl border border-gray-100 p-12 text-center">
          <div className="w-16 h-16 bg-gradient-to-br from-blue-100 to-cyan-100 rounded-2xl flex items-center justify-center mx-auto mb-4">
            <Send size={24} className="text-blue-500" />
          </div>
          <h3 className="text-base font-semibold text-gray-900 mb-1">No Sequences Yet</h3>
          <p className="text-xs text-gray-500 max-w-sm mx-auto mb-4">
            Create multi-step outreach cadences to automate your prospecting. Add email, LinkedIn, call, and task steps with AI-generated content.
          </p>
          <button
            onClick={() => setShowNewModal(true)}
            className="px-5 py-2.5 bg-blue-600 text-white text-sm font-medium rounded-lg hover:bg-blue-700"
          >
            Create Your First Sequence
          </button>
        </div>
      ) : (
        <div className="grid grid-cols-1 md:grid-cols-2 gap-3">
          {sequences.map((seq) => (
            <SequenceCard
              key={seq.id}
              sequence={seq}
              onSelect={handleSelectSequence}
              onToggleStatus={(id, status) => updateSequence(id, { status })}
              onDelete={deleteSequence}
            />
          ))}
        </div>
      )}

      <NewSequenceModal
        isOpen={showNewModal}
        onClose={() => setShowNewModal(false)}
        onCreate={createSequence}
      />
    </div>
  );
}
