/**
 * useSequences — React hook for the Sequences / Cadences workflow.
 *
 * CRUD for multi-step outreach sequences, enrollments,
 * and AI step-content generation.
 */

import { useState, useEffect, useCallback } from 'react';
import { supabase } from '../supabaseClient';

// ── Types ──────────────────────────────────────────────────

export interface Sequence {
  id: string;
  organization_id: string;
  created_by?: string;
  name: string;
  description?: string;
  status: 'draft' | 'active' | 'paused' | 'completed' | 'archived';
  default_channel: string;
  send_window_start?: string;
  send_window_end?: string;
  send_timezone?: string;
  skip_weekends: boolean;
  total_steps: number;
  total_enrolled: number;
  total_completed: number;
  total_replied: number;
  tags: string[];
  metadata: Record<string, any>;
  created_at: string;
  updated_at: string;
  steps?: SequenceStep[];
}

export interface SequenceStep {
  id: string;
  sequence_id: string;
  step_number: number;
  channel: 'email' | 'linkedin' | 'call' | 'task';
  delay_days: number;
  subject?: string;
  body?: string;
  ai_generated: boolean;
  ai_prompt?: string;
  tone: string;
  send_if: string;
  skip_if_replied: boolean;
  metadata: Record<string, any>;
  created_at: string;
}

export interface SequenceEnrollment {
  id: string;
  sequence_id: string;
  prospect_id?: string;
  enrolled_by?: string;
  current_step: number;
  status: 'active' | 'paused' | 'completed' | 'replied' | 'bounced' | 'unsubscribed' | 'removed';
  enrolled_at: string;
  last_step_at?: string;
  next_step_at?: string;
  completed_at?: string;
  prospect_name?: string;
  prospect_email?: string;
  prospect_company?: string;
  metadata: Record<string, any>;
  created_at: string;
}

export interface SequenceSummary {
  totalSequences: number;
  activeSequences: number;
  totalEnrolled: number;
  totalReplied: number;
  avgCompletionRate: number;
  byStatus: Record<string, number>;
}

interface SequencesState {
  sequences: Sequence[];
  summary: SequenceSummary;
  activeSequence: Sequence | null;
  enrollments: SequenceEnrollment[];
  loading: boolean;
  error: string | null;
}

const emptySummary: SequenceSummary = {
  totalSequences: 0, activeSequences: 0, totalEnrolled: 0,
  totalReplied: 0, avgCompletionRate: 0, byStatus: {},
};

// ── Hook ───────────────────────────────────────────────────

export function useSequences(organizationId: string, userId?: string) {
  const [state, setState] = useState<SequencesState>({
    sequences: [],
    summary: emptySummary,
    activeSequence: null,
    enrollments: [],
    loading: true,
    error: null,
  });

  const patch = useCallback((p: Partial<SequencesState>) => setState((prev) => ({ ...prev, ...p })), []);

  // ── Fetch all sequences ────────────────────────────────

  const fetchSequences = useCallback(async () => {
    if (!organizationId) { patch({ loading: false }); return; }
    patch({ loading: true, error: null });

    try {
      const { data, error } = await supabase
        .from('engage_sequences')
        .select('*')
        .eq('organization_id', organizationId)
        .order('updated_at', { ascending: false });

      if (error) throw error;

      const sequences: Sequence[] = data || [];

      // Summary
      const byStatus: Record<string, number> = {};
      let totalEnrolled = 0, totalReplied = 0, completedSum = 0, enrolledSum = 0;
      sequences.forEach((s) => {
        byStatus[s.status] = (byStatus[s.status] || 0) + 1;
        totalEnrolled += s.total_enrolled;
        totalReplied += s.total_replied;
        completedSum += s.total_completed;
        enrolledSum += s.total_enrolled;
      });

      patch({
        sequences,
        summary: {
          totalSequences: sequences.length,
          activeSequences: byStatus['active'] || 0,
          totalEnrolled,
          totalReplied,
          avgCompletionRate: enrolledSum > 0 ? Math.round((completedSum / enrolledSum) * 100) : 0,
          byStatus,
        },
        loading: false,
      });
    } catch (err: any) {
      patch({ error: err.message, loading: false });
    }
  }, [organizationId, patch]);

  // ── Fetch single sequence with steps ───────────────────

  const fetchSequenceDetail = useCallback(async (sequenceId: string) => {
    patch({ loading: true, error: null });
    try {
      const [seqRes, stepsRes, enrollRes] = await Promise.all([
        supabase.from('engage_sequences').select('*').eq('id', sequenceId).single(),
        supabase.from('engage_sequence_steps').select('*').eq('sequence_id', sequenceId).order('step_number'),
        supabase.from('engage_sequence_enrollments').select('*').eq('sequence_id', sequenceId).order('enrolled_at', { ascending: false }).limit(100),
      ]);

      if (seqRes.error) throw seqRes.error;

      const seq: Sequence = { ...seqRes.data, steps: stepsRes.data || [] };
      patch({ activeSequence: seq, enrollments: enrollRes.data || [], loading: false });
    } catch (err: any) {
      patch({ error: err.message, loading: false });
    }
  }, [patch]);

  // ── Create a sequence ──────────────────────────────────

  const createSequence = useCallback(async (seq: Partial<Sequence>) => {
    if (!organizationId) throw new Error('Organization ID is required. Please reload the page.');
    const { data, error } = await supabase
      .from('engage_sequences')
      .insert({
        organization_id: organizationId,
        created_by: userId || null,
        name: seq.name,
        description: seq.description || null,
        status: seq.status || 'draft',
        default_channel: seq.default_channel || 'email',
        skip_weekends: seq.skip_weekends ?? true,
        total_steps: 0,
        total_enrolled: 0,
        total_completed: 0,
        total_replied: 0,
        tags: seq.tags || [],
        metadata: seq.metadata || {},
      })
      .select()
      .single();
    if (error) throw error;
    await fetchSequences();
    return data;
  }, [organizationId, userId, fetchSequences]);

  // ── Update a sequence ──────────────────────────────────

  const updateSequence = useCallback(async (id: string, updates: Partial<Sequence>) => {
    const { error } = await supabase
      .from('engage_sequences')
      .update({ ...updates, updated_at: new Date().toISOString() })
      .eq('id', id);
    if (error) throw error;
    await fetchSequences();
  }, [fetchSequences]);

  // ── Delete a sequence ──────────────────────────────────

  const deleteSequence = useCallback(async (id: string) => {
    const { error } = await supabase.from('engage_sequences').delete().eq('id', id);
    if (error) throw error;
    patch({ activeSequence: null });
    await fetchSequences();
  }, [fetchSequences, patch]);

  // ── Add / update a step ────────────────────────────────

  const upsertStep = useCallback(async (step: Partial<SequenceStep> & { sequence_id: string }) => {
    const { data, error } = await supabase
      .from('engage_sequence_steps')
      .upsert(step)
      .select()
      .single();
    if (error) throw error;

    // Update step count
    const { count } = await supabase
      .from('engage_sequence_steps')
      .select('id', { count: 'exact', head: true })
      .eq('sequence_id', step.sequence_id);
    await supabase
      .from('engage_sequences')
      .update({ total_steps: count || 0, updated_at: new Date().toISOString() })
      .eq('id', step.sequence_id);

    if (state.activeSequence?.id === step.sequence_id) {
      await fetchSequenceDetail(step.sequence_id);
    }
    return data;
  }, [state.activeSequence, fetchSequenceDetail]);

  // ── Delete a step ──────────────────────────────────────

  const deleteStep = useCallback(async (stepId: string, sequenceId: string) => {
    const { error } = await supabase.from('engage_sequence_steps').delete().eq('id', stepId);
    if (error) throw error;
    if (state.activeSequence?.id === sequenceId) {
      await fetchSequenceDetail(sequenceId);
    }
  }, [state.activeSequence, fetchSequenceDetail]);

  // ── Enroll a prospect ──────────────────────────────────

  const enrollProspect = useCallback(async (sequenceId: string, prospect: {
    prospect_id?: string; prospect_name?: string; prospect_email?: string; prospect_company?: string;
  }) => {
    const { data, error } = await supabase
      .from('engage_sequence_enrollments')
      .insert({
        sequence_id: sequenceId,
        enrolled_by: userId,
        ...prospect,
      })
      .select()
      .single();
    if (error) throw error;

    // Update enrolled count
    await supabase.rpc('increment_field', {
      table_name: 'engage_sequences',
      field_name: 'total_enrolled',
      row_id: sequenceId,
    }).then(() => {}).catch(() => {
      // Fallback if RPC doesn't exist
      supabase.from('engage_sequences')
        .update({ total_enrolled: (state.sequences.find(s => s.id === sequenceId)?.total_enrolled || 0) + 1 })
        .eq('id', sequenceId);
    });

    await fetchSequences();
    return data;
  }, [userId, state.sequences, fetchSequences]);

  // ── Update enrollment status ───────────────────────────

  const updateEnrollmentStatus = useCallback(async (enrollmentId: string, status: SequenceEnrollment['status']) => {
    const updates: any = { status };
    if (status === 'completed') updates.completed_at = new Date().toISOString();
    const { error } = await supabase
      .from('engage_sequence_enrollments')
      .update(updates)
      .eq('id', enrollmentId);
    if (error) throw error;
  }, []);

  // ── Generate AI step content ───────────────────────────

  const generateStepContent = useCallback(async (sequenceId: string, stepNumber: number, context: {
    prospectName?: string; companyName?: string; channel: string; tone: string; previousSteps?: string[];
  }) => {
    const { data, error } = await supabase.functions.invoke('engage-sequences', {
      body: {
        action: 'generate_step',
        sequence_id: sequenceId,
        step_number: stepNumber,
        ...context,
      },
    });
    if (error) throw new Error(error.message);
    if (data?.error) throw new Error(data.error);
    return data;
  }, []);

  // ── Init ───────────────────────────────────────────────

  useEffect(() => {
    fetchSequences();
  }, [fetchSequences]);

  return {
    ...state,
    fetchSequences,
    fetchSequenceDetail,
    createSequence,
    updateSequence,
    deleteSequence,
    upsertStep,
    deleteStep,
    enrollProspect,
    updateEnrollmentStatus,
    generateStepContent,
  };
}
